#pragma once

#include "core/templates/vector.h"
#include "core/string/string_name.h"
#include "core/string/ustring.h"

// Canvas-to-RD shader translation for the RD-direct backend (plan P2).
// The stock shader corpus is machine-generated by this fork's JSL compiler
// into a small canvas_item dialect: three fixed varying assignments in
// vertex() (UV / CUSTOM0.xy / COLOR), a fragment() that is one expression
// (plus an optional discard) over those varyings, loose `uniform` value and
// sampler declarations, and helper functions in between. Translation is
// header surgery on that dialect: the fragment body already is raw GLSL.
//
// Value uniforms (scalars and arrays) ride a std140 uniform buffer bound on
// set 0 right after the samplers; the canonical draw header (transform,
// modulate, pixel->NDC, optional target_size) stays in the push constant.
// Offsets/strides below mirror std140 rules so the host packs identical bytes.
namespace godot_javafx {

struct RdValueUniform {
	StringName name;
	int offset = 0; // Byte offset inside the uniform buffer.
	int words = 0; // 32-bit words per element (1-4).
	int count = 1; // Array element count; 1 for scalars and one-element arrays.
	int stride = 0; // Bytes per array element (std140 rounds to 16).
	bool is_array = false; // count==1 is ambiguous: weights[1] is an array.
	bool integer = false;
};

struct RdShaderSources {
	bool ok = false;
	String error;
	String vertex_source;
	String fragment_source;
	Vector<StringName> sampler_names; // Binding order follows declaration order.
	// A hint_screen_texture sampler (runtime LCD variant) samples a snapshot
	// of the destination taken before its first sampling draw in the pass;
	// its index into sampler_names.
	int screen_sampler_index = -1;
	enum BlendMode { BLEND_PREMUL, BLEND_DISABLED, BLEND_ADD, BLEND_MUL };
	BlendMode blend_mode = BLEND_PREMUL; // render_mode blend_* (corpus is premul).
	Vector<RdValueUniform> value_uniforms;
	int push_constant_bytes = 0; // Canonical header only.
	int value_buffer_bytes = 0; // std140 uniform buffer size, 0 when no values.
	Vector<uint8_t> value_defaults; // std140 bytes evaluated by Godot's canvas parser.
};

RdShaderSources translate_canvas_shader(const String &p_canvas_source);

} // namespace godot_javafx
